"""`harness state migrate` — split a legacy `docs/state/features.json` into
the new two-tier layout (index + per-feature state files).

Pre-migration:
    docs/state/features.json   { "BKM-01": { ...full record... }, ... }

Post-migration:
    docs/state/features.json   { "BKM-01": { ...slim status mirror... }, ... }
    docs/features/BKM-01/state.json  { ...full record... }

Rules:
- Pre-plan features (`phase` ∈ {imported, story, story-validated, research}):
  stay entirely in the index. No per-feature file is created.
- Post-plan features (`phase` ∈ {plan-requirements, plan-requirements-approved,
  plan-implementation, implementation, review, security-reviewed}): full record
  is written to `docs/features/<id>/state.json` and the index entry is slimmed
  to the status-mirror shape.
- Empty index → no-op.

Idempotent: re-running detects already-migrated features (per-feature file
exists, index entry already slim) and skips them.

Backups: writes `docs/state/features.json.pre-migrate-<iso8601>.bak` before
mutating the index.
"""

from __future__ import annotations

import json
import shutil
from datetime import datetime
from pathlib import Path
from typing import Any

from rich.console import Console
from rich.table import Table

_console = Console()
_err = Console(stderr=True)

# Field set kept in the index entry (status mirror; everything else moves to
# the per-feature file).
_INDEX_FIELDS: set[str] = {
    "story",
    "story_priority",
    "research",
    "research_verdict",
    "prd",
    "design",
    "gate",
    "plan",
    "impl",
    "validation",
    "review",
    "security",
    "tracker_story",
    "tracker_research",
    "tracker_prd",
    "tracker_plan",
    "rtm_source_sha",
    "phase",
    "last_updated",
}

_POST_PLAN_PHASES: set[str] = {
    "plan-requirements",
    "plan-requirements-approved",
    "plan-implementation",
    "implementation",
    "review",
    "security-reviewed",
}


def cmd_state_migrate(*, project_root: Path | None = None, dry_run: bool = False) -> int:
    """Split legacy index into per-feature files. Returns process exit code."""
    root = project_root or Path.cwd()
    index_path = root / "docs" / "state" / "features.json"
    if not index_path.is_file():
        _err.print(f"[red]index file not found at {index_path}[/red]")
        _err.print("[dim]run from a project root with .claude/ initialised[/dim]")
        return 1

    try:
        index = json.loads(index_path.read_text(encoding="utf-8"))
    except json.JSONDecodeError as exc:
        _err.print(f"[red]index file invalid JSON: {exc}[/red]")
        return 1
    if not isinstance(index, dict):
        _err.print("[red]index root must be an object[/red]")
        return 1

    if not index:
        _console.print("[dim]index is empty; nothing to migrate[/dim]")
        return 0

    features_root = root / "docs" / "features"
    moves: list[dict[str, Any]] = []
    new_index: dict[str, dict[str, Any]] = {}

    for fid, record in index.items():
        if not isinstance(record, dict):
            _err.print(f"[yellow]skip {fid}: record is not an object[/yellow]")
            new_index[fid] = record
            continue
        phase = record.get("phase")
        is_post_plan = phase in _POST_PLAN_PHASES
        target = features_root / fid / "state.json"

        if is_post_plan:
            already = target.is_file()
            moves.append({
                "fid": fid,
                "phase": phase,
                "action": "skip (already migrated)" if already else "write per-feature + slim index",
                "target": target,
                "record": record,
            })
            new_index[fid] = {k: v for k, v in record.items() if k in _INDEX_FIELDS}
        else:
            # Pre-plan — keep full record in the index. Nothing moves.
            moves.append({
                "fid": fid,
                "phase": phase or "unknown",
                "action": "keep in index (pre-plan)",
                "target": None,
                "record": record,
            })
            new_index[fid] = record

    tbl = Table(show_header=True, header_style="bold", title="Migration plan")
    tbl.add_column("Feature")
    tbl.add_column("Phase")
    tbl.add_column("Action")
    for m in moves:
        tbl.add_row(m["fid"], m["phase"], m["action"])
    _console.print(tbl)

    if dry_run:
        _console.print("[yellow]--dry-run: no writes[/yellow]")
        return 0

    # Backup index
    backup = index_path.with_name(f"features.json.pre-migrate-{_now_iso_compact()}.bak")
    shutil.copy2(index_path, backup)
    _console.print(f"[dim]backup → {backup.relative_to(root)}[/dim]")

    # Write per-feature files for post-plan features
    written = 0
    skipped = 0
    for m in moves:
        if m["target"] is None:
            continue
        target: Path = m["target"]
        if target.is_file():
            skipped += 1
            continue
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(json.dumps(m["record"], indent=2, default=str) + "\n", encoding="utf-8")
        written += 1

    # Write slim index
    index_path.write_text(json.dumps(new_index, indent=2, default=str) + "\n", encoding="utf-8")

    _console.print(
        f"[green]migrated[/green] {written} feature(s) to per-feature files, "
        f"skipped {skipped} already-migrated, slimmed index to {len(new_index)} entries"
    )
    return 0


def _now_iso_compact() -> str:
    return datetime.utcnow().strftime("%Y%m%dT%H%M%SZ")
